do $$declare snap jsonb;job jsonb;capdate date;
begin
 snap:=jsonb_build_object('capsules',(select jsonb_agg(to_jsonb(c)) from public.capsules c where c.id='77777777-7777-4777-8777-777777777777'),'messages',(select jsonb_agg(to_jsonb(m)) from public.messages m where m.capsule_id='77777777-7777-4777-8777-777777777777'));
 job:=public.admin_backend('import',jsonb_build_object('snapshot',snap,'files','[]'::jsonb,'aad','55555555-5555-4555-8555-555555555555/manifest'));
 perform public.admin_backend('import_finish',job);
 if not exists(select 1 from la_suite_internal.backups where id=(job->>'id')::uuid and state='restoring') then raise exception 'Import queue failed';end if;
 update public.capsules set couple_name='Nouveau réglage' where id='77777777-7777-4777-8777-777777777777';
 delete from public.messages where id='88888888-8888-4888-8888-888888888888';
 insert into public.messages(capsule_id,guest_name,message_text,media_type,delivery_at) values('77777777-7777-4777-8777-777777777777','Autre','Nouvelle contribution','text',now());
 perform public.admin_backend('restore_metadata',jsonb_build_object('snapshot',snap));
 if (select couple_name from public.capsules where id='77777777-7777-4777-8777-777777777777')<>'Nouveau réglage' then raise exception 'Restore overwrote newer settings';end if;
 if (select count(*) from public.messages where capsule_id='77777777-7777-4777-8777-777777777777')<>2 then raise exception 'Restore lost newer contribution';end if;
 if (select delivery_at from public.messages where id='88888888-8888-4888-8888-888888888888')<>(snap->'messages'->0->>'delivery_at')::timestamptz then raise exception 'Restore changed reveal date';end if;
 delete from public.capsules where id='77777777-7777-4777-8777-777777777777';
 perform public.admin_backend('restore_metadata',jsonb_build_object('snapshot',snap));
 if not exists(select 1 from public.capsules where id='77777777-7777-4777-8777-777777777777' and couple_name='Original') then raise exception 'Missing capsule restore failed';end if;
end $$;
